def parse(s):
 m=re.match(r'\\A---\\r?\\n(.*?)\\r?\\n---\\r?\\n',s,re.S);return (yaml.safe_load(m.group(1)),s[m.end():]) if m else ({},s)
paths=subprocess.run(['git','-c','core.excludesFile=','ls-tree','-r','--name-only',rev],capture_output=True,text=True,check=True).stdout.splitlines();counts=collections.defaultdict(collections.Counter);actors=collections.defaultdict(list)
